const body = $input.first().json.body || {};
return [{
  json: {
    docId: 'cRP1WgZQv7KmwmVrUbuEF8',
    userId: Number(body.userId),
    cardId: Number(body.cardId),
    finish: (body.finish || '').toString() || null,
    quality: (body.quality || '').toString() || null
  }
}];

function refId(v) { return Array.isArray(v) ? v[1] : v; }
const config = $('Set Config').first().json;
const cardsRows = $('Get Cards').all().map((i) => i.json).filter((r) => r.id != null);
const raritiesRows = $('Get Rarities').all().map((i) => i.json).filter((r) => r.id != null);
const pullsRows = $('Get Pulls').all().map((i) => i.json).filter((r) => r.id != null);
const usersRows = $('Get Users').all().map((i) => i.json).filter((r) => r.id != null);
const finishRows = $('Get Finishes').all().map((i) => i.json).filter((r) => r.id != null);
const qualityRows = $('Get Qualities').all().map((i) => i.json).filter((r) => r.id != null);

const card = cardsRows.find((c) => c.id === config.cardId);
if (!card) return [{ json: { ok: false, error: 'card_not_found' } }];
if (card.IsPromo) return [{ json: { ok: false, error: 'promo_not_disenchantable' } }];

const FINISH_ORDER = ['normal', 'holo', 'gold', 'ghost', 'diamond', 'rainbow'];
const QUALITY_ORDER = ['damaged', 'worn', 'good', 'mint'];
function finishOf(p) { return p.Finish || 'normal'; }
function qualityOf(p) { return p.Quality || 'damaged'; }
// Decrafte toujours l'exemplaire le MOINS prestigieux en premier (finition
// d'abord, puis qualite parmi les doublons de meme finition) : jamais un
// holo/gold/.../mint par erreur s'il reste un exemplaire normal/abime - SAUF
// si l'appelant precise exactement quelle variante cibler (config.finish/
// config.quality, envoye par une vignette de collection qui affiche desormais
// une pile distincte par finition+qualite) : dans ce cas on cible cette
// variante exacte, pour ne jamais decrafter une variante differente de celle
// que le joueur a cliquee.
let myMatchingPulls = pullsRows.filter((p) => refId(p.User) === config.userId && refId(p.Card) === config.cardId);
if (!myMatchingPulls.length) return [{ json: { ok: false, error: 'card_not_owned' } }];
if (config.finish && config.quality) {
  const exact = myMatchingPulls.filter((p) => finishOf(p) === config.finish && qualityOf(p) === config.quality);
  if (!exact.length) return [{ json: { ok: false, error: 'variant_not_owned' } }];
  myMatchingPulls = exact;
}
const pull = [...myMatchingPulls].sort((a, b) => (FINISH_ORDER.indexOf(finishOf(a)) - FINISH_ORDER.indexOf(finishOf(b))) || (QUALITY_ORDER.indexOf(qualityOf(a)) - QUALITY_ORDER.indexOf(qualityOf(b))))[0];

const user = usersRows.find((u) => u.id === config.userId);
if (!user) return [{ json: { ok: false, error: 'unknown_user' } }];

const rarity = raritiesRows.find((r) => r.id === refId(card.Rarity));
const pullFinish = finishOf(pull);
const pullQuality = qualityOf(pull);
const finishRow = finishRows.find((f) => f.Key === pullFinish);
const finishMultiplier = finishRow ? (finishRow.DisenchantMultiplier || 1) : 1;
const qualityRow = qualityRows.find((q) => q.Key === pullQuality);
const qualityMultiplier = qualityRow ? (qualityRow.DisenchantMultiplier || 1) : 1;
const dustGained = Math.round((rarity ? (rarity.DisenchantValue || 0) : 0) * finishMultiplier * qualityMultiplier);
const newStardust = (user.StardustCount || 0) + dustGained;

return [{
  json: {
    ok: true,
    docId: config.docId,
    userId: config.userId,
    pullRowId: pull.id,
    cardName: card.Name,
    finish: pullFinish,
    quality: pullQuality,
    dustGained,
    newStardust
  }
}];
